def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Simple implementation to find first difference
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[-1] if s_in else "", s_out[pos:], pos) if len(s_out) > len(s_in) else ("", "", -1)
        elif len(s_in) > len(s_out):
            return (s_in[pos:], "", pos) if pos >= 0 else ("", s_out[-1], len(s_in)-1)
        else:
            return ("", "", -1)  # No change

    # Find what we're replacing
    old_sub = ""
    new_sub = ""

    # Check if we're inserting or replacing
    if len(s_in) <= len(s_out):
        # Insertion or replacement
        old_sub = s_in[pos:pos+1]
        new_sub = s_out[pos:pos+1]
    else:
        # Deletion or replacement  
        old_sub = s_in[pos:pos+1]
        new_sub = s_out[pos:pos+1]

    return (old_sub, new_sub, pos)

# Analyze the two changed cases
changed = [(0, 'zykju', 'zxfukju'), (1, 'xcju', 'xkiaju')]

for idx, inp, outp in changed:
    old, new, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' → '{outp}'")
    print(f"  Change: '{old}' → '{new}' at position {pos}")
    print()

